# ═════════════════════════════════════════════════════════════════
# ═══════════════ 正文代码开始（↑ 以上均为内嵌资源区） ═══════════════
# ═════════════════════════════════════════════════════════════════

# ---------------- 网格地图 ----------------
def in_bounds(c, r):
    return 0 <= c < GRID and 0 <= r < GRID


def tank_area(c, r):
    """坦克占 1x1 格：一个方块大小，恰好覆盖所在格"""
    return [(c, r)]


def walkable(grid, c, r):
    # 基地是装饰且不可摧毁；草坪/传送门均可通行（门不挡路只传送）
    return in_bounds(c, r) and grid[r][c] in (EMPTY, BASE, GRASS, PORTAL)


def can_stand(grid, c, r, blocked=frozenset()):
    if not in_bounds(c, r):
        return False
    return all(walkable(grid, cc, rr) and (cc, rr) not in blocked
               for cc, rr in tank_area(c, r))


def exit_count(grid, c, r):
    """局部环境识别的地基：格子四邻可走出口数（迷宫结构分析）"""
    return sum(1 for dc, dr in DIRS if walkable(grid, c + dc, r + dr))


def is_deadend(grid, c, r):
    return exit_count(grid, c, r) <= 1


def nearest_junction(grid, c, r, max_depth=6):
    """BFS 最近开阔点（出口>=3）：死胡同脱困的强制重规划终点"""
    queue, seen = [(c, r, 0)], {(c, r)}
    for cc, rr, depth in queue:
        if depth and exit_count(grid, cc, rr) >= 3:
            return (cc, rr)
        if depth >= max_depth:
            continue
        for dc, dr in DIRS:
            cell = (cc + dc, rr + dr)
            if cell not in seen and walkable(grid, *cell):
                seen.add(cell)
                queue.append((cell[0], cell[1], depth + 1))
    return None


class Intel:
    """战场情报中心：任一 AI 目击玩家即全网共享；3 秒新鲜度即可信度过滤"""

    TTL = 3.0

    def __init__(self):
        self.reset()

    def reset(self):
        self.pos, self.seen_at = None, -1e9

    def report(self, player, now):
        self.pos, self.seen_at = player.center(), now

    def fresh_pos(self, now):
        return self.pos if now - self.seen_at <= self.TTL else None


INTEL = Intel()


MAZE_N = 12            # 迷宫块数：12x12 个 2x2 块恰好覆盖 24x24 坦克起点格
PLAZA = (1, 4, 10, 7)  # 中央广场块范围(i0,j0,i1,j1)：YXF 字母展示区兼迷宫枢纽
STEEL_RATE = 0.15      # 迷宫墙转钢墙比例：钢为骨架，砖可炸开路
BRAID_RATE = 0.35      # 死胡同打通比例：成环提升遭遇战机动力


def configure_level(level):
    """关卡几何装配：0=普通模式复原原始布局；N=无尽第 N 关（地图x1.5、敌军+2）"""
    global GRID, MAZE_N, PLAZA, PLAYER_SPAWN, AI_SPAWNS, MAP_PX, VIEW_SCALE
    if level <= 0:
        GRID, MAZE_N = 25, 12
        PLAZA = (1, 4, 10, 7)
        PLAYER_SPAWN = (11, 23)
        AI_SPAWNS = ((0, 0), (11, 2), (23, 0))
    else:
        GRID = min(GRID_MAX, max(25, int(25 * 1.5 ** (level - 1)) | 1))  # 至多 1.5³ 倍
        MAZE_N = (GRID - 1) // 2
        mid = MAZE_N // 2
        PLAZA = (mid - 4, mid - 3, mid + 4, mid + 3)
        PLAYER_SPAWN = (GRID // 2, GRID - 2)
        n = min(ENEMY_CAP, 3 + 2 * (level - 1))   # 与地图同步：双双封顶
        AI_SPAWNS = tuple((min(GRID - 2, int(GRID * (k + 0.5) / n)), 0)
                          for k in range(n))
    MAP_PX = GRID * CELL
    VIEW_SCALE = SCREEN_W / MAP_PX       # 整幅自适应：25 格恰为 1.0 与原版一致


def block_neighbors(b):
    """迷宫块的四邻块（越界剔除）"""
    i, j = b
    return [(i + dx, j + dy) for dx, dy in DIRS
            if 0 <= i + dx < MAZE_N and 0 <= j + dy < MAZE_N]


def carve_maze():
    """迭代回溯法雕完美迷宫：节点隔 2 块分布，走廊与墙均 1 块厚(=坦克宽)"""
    start = (0, 0)                          # 节点必须落在偶数块上
    open_blocks, stack = {start}, [start]
    while stack:
        cur = stack[-1]
        cand = [(cur[0] + 2 * dx, cur[1] + 2 * dy) for dx, dy in DIRS
                if 0 <= cur[0] + 2 * dx < MAZE_N and 0 <= cur[1] + 2 * dy < MAZE_N
                and (cur[0] + 2 * dx, cur[1] + 2 * dy) not in open_blocks]
        if not cand:
            stack.pop()
            continue
        nxt = random.choice(cand)
        open_blocks.add(((cur[0] + nxt[0]) // 2, (cur[1] + nxt[1]) // 2))  # 打通中间墙
        open_blocks.add(nxt)
        stack.append(nxt)
    return open_blocks


def braid_maze(open_blocks):
    """按比例打通死胡同成环：完美迷宫单路进出，对遭遇战过憋屈"""
    for b in list(open_blocks):
        if random.random() >= BRAID_RATE:
            continue
        open_nb = [n for n in block_neighbors(b) if n in open_blocks]
        walls = [n for n in block_neighbors(b) if n not in open_blocks]
        if len(open_nb) == 1 and walls:     # 只处理死胡同
            open_blocks.add(random.choice(walls))


def carve_plaza(open_blocks):
    """中央广场：清出 YXF 展示区，同时充当迷宫上下半区的枢纽"""
    i0, j0, i1, j1 = PLAZA
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            open_blocks.add((i, j))


def force_open_spawns(open_blocks):
    """出生点与基地周边强制开放：按当前出生格换算覆盖块，迷宫再缠也不能堵门"""
    for c, r in list(AI_SPAWNS) + [PLAYER_SPAWN]:
        for bi in {c // 2, (c + 1) // 2}:
            for bj in {r // 2, (r + 1) // 2}:
                open_blocks.add((bi, bj))


def separate_spawns(open_blocks):
    """顶角出生视线走第1行(块行j=0)：砌墙隔断，根除同排出生对射秒杀
    (3,0)/(8,0) 是迷宫树边，关闭可能切连通 → 交给 generate_map 重试兜底；
    (3,1)/(8,1) 是奇奇块非结构块，砌墙零风险，作第二视线屏障"""
    if AI_SPAWNS != ((0, 0), (11, 2), (23, 0)):
        return                             # 无尽模式出生点分散，无需此屏障
    open_blocks.discard((3, 0))
    open_blocks.discard((8, 0))
    open_blocks.discard((3, 1))
    open_blocks.discard((8, 1))


def paint_walls(grid, open_blocks):
    """迷宫墙落格：随机 15% 升级钢墙作骨架，其余砖墙可炸开路"""
    for j in range(MAZE_N):
        for i in range(MAZE_N):
            if (i, j) in open_blocks:
                continue
            material = STEEL if random.random() < STEEL_RATE else BRICK
            for dr in (0, 1):
                for dc in (0, 1):
                    grid[2 * j + dr][2 * i + dc] = material


YXF_GLYPHS = {   # 5x5 点阵：地图中央用砖墙拼出姓名首字母，证明原创（加分项）
    "Y": ("X...X", "X...X", "..X..", "..X..", "..X.."),
    "X": ("X...X", ".X.X.", "..X..", ".X.X.", "X...X"),
    "F": ("XXXXX", "X....", "XXXX.", "X....", "X...."),
}


def carve_yxf(grid):
    """先清空中央条带再摆 YXF 砖阵：坐标按 GRID 动态居中（25 格时与原版重合）"""
    cx = GRID // 2
    for r in range(cx - 3, cx + 4):
        for c in range(max(3, cx - 9), min(GRID - 3, cx + 10)):
            grid[r][c] = EMPTY
    for letter, col0 in (("Y", cx - 8), ("X", cx - 2), ("F", cx + 4)):
        for dr, row in enumerate(YXF_GLYPHS[letter]):
            for dc, ch in enumerate(row):
                if ch == "X":
                    grid[cx - 2 + dr][col0 + dc] = BRICK


def reachable_origins(grid, start):
    """BFS 求坦克原点可达集，用于连通性校验"""
    seen, stack = {start}, [start]
    while stack:
        c, r = stack.pop()
        for dc, dr in DIRS:
            nxt = (c + dc, r + dr)
            if nxt not in seen and can_stand(grid, *nxt):
                seen.add(nxt)
                stack.append(nxt)
    return seen


def place_base(grid):
    for c, r in tank_area(*PLAYER_SPAWN):
        grid[r][c] = BASE


def near_any_spawn(c, r):
    """出生区判定：坦克 2x2 起身位外扩一格不种草，防开局即隐身"""
    return any(abs(c - sc) <= 1 and abs(r - sr) <= 1
               for sc, sr in list(AI_SPAWNS) + [PLAYER_SPAWN])


def plant_grass(grid):
    """草坪丛：只长在空地且避开出生区——进草隐身，可走可穿弹"""
    clumps = max(6, GRID * GRID // 80)
    for _ in range(clumps * 4):          # 拒绝采样：命中即种一丛
        c, r = random.randrange(GRID), random.randrange(GRID)
        for dc, dr in ((0, 0), (1, 0), (0, 1), (1, 1))[:random.choice((2, 3, 4))]:
            cc, rr = c + dc, r + dr
            if in_bounds(cc, rr) and grid[rr][cc] == EMPTY \
                    and not near_any_spawn(cc, rr):
                grid[rr][cc] = GRASS


def place_portals(grid):
    """成对传送门：只在空地且避开出生区；同对间距≥8格，异对间距≥3格"""
    global PORTAL_PAIRS, PORTAL_MAP
    PORTAL_PAIRS, PORTAL_MAP = [], {}
    spots = [(c, r) for r in range(GRID) for c in range(GRID)
             if grid[r][c] == EMPTY and not near_any_spawn(c, r)]
    pairs = min(max(2, GRID // 12), len(spots) // 2)
    for _ in range(pairs):
        free = [s for s in spots
                if s not in PORTAL_MAP
                and all(abs(s[0] - o[0]) + abs(s[1] - o[1]) >= 3 for o in PORTAL_MAP)]
        far = lambda p, q: abs(p[0] - q[0]) + abs(p[1] - q[1]) >= 8
        anchors = [s for s in free if any(far(s, o) for o in free if o != s)]
        if not anchors:
            break                       # 空地不足：宁缺毋滥，少布一对
        a = random.choice(anchors)      # 先锁定有远伴侣的锚点，配对必不落空
        b = random.choice([s for s in free if s != a and far(s, a)])
        PORTAL_PAIRS.append((a, b))
        PORTAL_MAP[a], PORTAL_MAP[b] = b, a
    for c, r in PORTAL_MAP:
        grid[r][c] = PORTAL
    LOG.info("传送门布点: %d 对 / %d 个", len(PORTAL_PAIRS), len(PORTAL_MAP))


def log_map(grid, attempt):
    bricks = sum(row.count(BRICK) for row in grid)
    steels = sum(row.count(STEEL) for row in grid)
    grasses = sum(row.count(GRASS) for row in grid)
    LOG.info("地图生成完毕: 尝试 %d 次, 砖 %d / 钢 %d / 草 %d (含 YXF 砖阵)",
             attempt, bricks, steels, grasses)


def generate_map():
    # 迷宫从玩家出生块起步雕刻，构造上连通；重试仅作异常兜底
    for attempt in range(1, 61):
        open_blocks = carve_maze()
        braid_maze(open_blocks)
        carve_plaza(open_blocks)
        force_open_spawns(open_blocks)
        separate_spawns(open_blocks)
        grid = [[EMPTY] * GRID for _ in range(GRID)]
        paint_walls(grid, open_blocks)
        carve_yxf(grid)
        plant_grass(grid)
        reach = reachable_origins(grid, PLAYER_SPAWN)
        if all(sp in reach for sp in AI_SPAWNS):
            place_base(grid)
            place_portals(grid)
            log_map(grid, attempt)
            return grid
    LOG.warning("连通校验 60 次未过，降级空图")
    grid = [[EMPTY] * GRID for _ in range(GRID)]  # 兜底：几乎不可能走到
    place_base(grid)
    place_portals(grid)
    return grid


# ---------------- 射线视野（Bresenham 遮挡检测） ----------------
def bresenham_cells(x0, y0, x1, y1):
    """整数 Bresenham：返回 (x0,y0)→(x1,y1) 穿过的格子序列"""
    cells = []
    dx, dy = abs(x1 - x0), -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    while True:
        cells.append((x0, y0))
        if x0 == x1 and y0 == y1:
            return cells
        e2 = 2 * err
        if e2 >= dy:
            err += dy
            x0 += sx
        if e2 <= dx:
            err += dx
            y0 += sy


def has_los(grid, a_center, b_center):
    """格子粒度遮挡判定，与子弹碰撞粒度保持一致"""
    ax, ay = a_center
    bx, by = b_center
    cells = bresenham_cells(int(ax) // CELL, int(ay) // CELL,
                            int(bx) // CELL, int(by) // CELL)
    for c, r in cells[1:-1]:        # 排除起终点自身格（坦克脚下无墙）
        if grid[r][c] in (BRICK, STEEL, GRASS):   # 草坪同样遮蔽视线
            return False
    # 目标自身藏草：进草即隐身，观察者直视也看不见
    end_c, end_r = cells[-1]
    if grid[end_r][end_c] == GRASS:
        return False
    return True


# ---------------- A* 寻路（四向 + 曼哈顿启发） ----------------
def rebuild_path(came, cur):
    path = [cur]
    while cur in came:
        cur = came[cur]
        path.append(cur)
    path.reverse()
    return path[1:]                # 去掉起点，仅保留待走步序


def astar(grid, start, goal):
    """在坦克原点图(24x24)上搜索；返回不含起点的步序，无可达路返回 None"""
    if start == goal:
        return []
    openq = [(abs(goal[0] - start[0]) + abs(goal[1] - start[1]), start)]
    gscore, came = {start: 0}, {}
    while openq:
        _, cur = heapq.heappop(openq)
        if cur == goal:
            return rebuild_path(came, cur)
        for dc, dr in DIRS:
            nxt = (cur[0] + dc, cur[1] + dr)
            if not can_stand(grid, *nxt):
                continue
            ng = gscore[cur] + 1
            if ng < gscore.get(nxt, 1 << 30):
                gscore[nxt] = ng
                came[nxt] = cur
                h = abs(goal[0] - nxt[0]) + abs(goal[1] - nxt[1])
                heapq.heappush(openq, (ng + h, nxt))
    return None


# ---------------- 坦克 ----------------
class Tank:
    SIZE = CELL               # 一个方块大小：车身与格子同尺寸
    HP = TANK_HP                # 血量定义在基类：所有子类共享同一套伤害机制
    COOLDOWN = 0.0
    STEP_TIME = PLAYER_STEP_TIME            # 每格耗时：子类覆盖实现差异化档速

    TURRET_FOLLOWS = False                  # 玩家炮塔独立旋转；AI 覆写为跟随车体

    def __init__(self, gc, gr, color, is_player):
        self.gc, self.gr = gc, gr
        self.px, self.py = gc * CELL, gr * CELL
        self.tgc, self.tgr = gc, gr
        self.tx, self.ty = self.px, self.py
        self.dir = (0, -1) if is_player else random.choice(DIRS)
        self.turret, self.turret_deg = 0, 0.0
        self.sync_turret_to_body()
        self.color = color
        self.is_player = is_player
        self.alive = True
        self.moving = False
        self.fire_cd = 0.0
        self.hp = self.HP

    def center(self):
        return (self.px + 16, self.py + 16)

    def rect(self):
        return pygame.Rect(int(self.px), int(self.py), self.SIZE, self.SIZE)

    def try_move(self, dc, dr, grid, blocked):
        # 仅在格点空闲时接受新指令 → 严格整格步进，A* 状态才稳定
        if self.moving or (dc, dr) == (0, 0):
            return False
        self.dir = (dc, dr)
        self.sync_turret_to_body()
        nc, nr = self.gc + dc, self.gr + dr
        if not can_stand(grid, nc, nr, blocked):
            return False
        self.moving = True
        self.tgc, self.tgr = nc, nr
        self.tx, self.ty = nc * CELL, nr * CELL
        return True

    def sync_turret_to_body(self):
        # 仅 AI 启用：炮塔档位锁死车体朝向，弹道与旧版 4 向完全一致
        if self.TURRET_FOLLOWS:
            self.turret = DIR_TO_TURRET.get(self.dir, self.turret)

    def rotate_turret(self, step):
        # 8 档环形步进：45° 定位由档位保证，补间只作用于视觉
        self.turret = (self.turret + step) % 8
        play_sound("turn")

    def sync_turret(self, dt):
        """显示角向档位角最短路径补间：540°/s，转向跟手不瞬跳"""
        diff = (self.turret * 45 - self.turret_deg + 540) % 360 - 180
        step = 540 * dt
        if abs(diff) <= step:
            self.turret_deg = (self.turret * 45) % 360
        else:
            self.turret_deg = (self.turret_deg + (step if diff > 0 else -step)) % 360

    def advance(self, dt):
        """像素向目标格补间，到达即吸附对齐，杜绝半格漂移"""
        self.sync_turret(dt)                 # 炮塔补间与移动解耦：静止转向同样平滑
        if not self.moving:
            return
        step = (CELL / self.STEP_TIME) * dt
        self.px += step * self.dir[0]
        self.py += step * self.dir[1]
        arrived = ((self.dir[0] > 0 and self.px >= self.tx) or
                   (self.dir[0] < 0 and self.px <= self.tx) or
                   (self.dir[1] > 0 and self.py >= self.ty) or
                   (self.dir[1] < 0 and self.py <= self.ty))
        if arrived:
            self.px, self.py = self.tx, self.ty
            self.gc, self.gr = self.tgc, self.tgr
            self.moving = False

    def teleport_to(self, gc, gr):
        """传送门落格：坐标整体重置 + AI 寻路/卡死状态全部失效重算"""
        self.gc, self.gr = gc, gr
        self.tgc, self.tgr = gc, gr
        self.px, self.py = gc * CELL, gr * CELL
        self.tx, self.ty = self.px, self.py
        self.moving = False
        self.path, self.repath = [], 0.0    # AITank 专用：玩家多出的属性无害
        self.last_cell, self.stuck = (gc, gr), 0.0
        self.trail = [(gc, gr)]

    def try_fire(self):
        if not self.alive or self.fire_cd > 0:
            return
        if any(b.owner is self for b in BULLETS):   # 经典设定：同时仅 1 颗弹
            return
        cx, cy = self.center()
        d = TURRET_DIRS[self.turret]         # 出膛向量随炮塔档位（8 向）
        # 出膛距离按最大轴向归一：斜向也保证每轴偏移 22px，
        # 否则 22×0.707≈15.6 < 自身半宽 16，出膛即重叠 → 斜射自杀（每轴需 >16+4）
        m = max(abs(d[0]), abs(d[1]))
        dist = 22 / m if m else 22.0
        BULLETS.append(Bullet(self, cx + d[0] * dist, cy + d[1] * dist, d))
        self.fire_cd = self.COOLDOWN
        play_sound("shoot")


class Player(Tank):
    COOLDOWN = 0.0

    def __init__(self, gc, gr):
        super().__init__(gc, gr, (104, 130, 58), True)   # 军橄榄绿：玩家木牛
        self.lives = 3
        self.invincible = INVINCIBLE_TIME   # 开局也送无敌：防 AI 天降远射秒杀
        self.respawn = 0.0


class AITank(Tank):
    COOLDOWN = AI_FIRE_CD
    STEP_TIME = AI_STEP_TIME                # AI 档速略慢，避免压迫感过强
    TURRET_FOLLOWS = True                   # AI 炮塔锁死车体：寻路/弹道行为与旧版一致

    def __init__(self, gc, gr, elite=False):
        super().__init__(gc, gr, (158, 96, 62), False)   # 深棕木色：敌军流马
        self.path = []
        self.goal = None
        if elite:                        # 无尽精英：火力/机动/反应三重强化
            self.COOLDOWN = ELITE_FIRE_CD
            self.STEP_TIME = ELITE_STEP_TIME
        self.repath_time = ELITE_REPATH if elite else AI_REPATH_TIME
        self.repath = random.uniform(0, self.repath_time)  # 错峰重算：大图防同帧 A* 洪峰
        self.grace = AI_GRACE_TIME           # 出生武器锁定：倒计时内只机动不开火
        self.trail = [(gc, gr)]              # 最近 8 格足迹：脱困回溯依据
        self.last_cell = (gc, gr)
        self.stuck = 0.0                     # 静止卡死累计：超阈值触发脱困
        self.escapes = 0                     # 脱困尝试计数：反复失败转冷静期
        self.calm = 0.0                      # 战术冷静期：只巡逻防抖

    # ---- 感知：直视上报情报网；无视线追全网最后目击点 ----
    def acquire_goal(self, grid, player, intel, now):
        if player.alive and has_los(grid, self.center(), player.center()):
            intel.report(player, now)        # 目击即共享：多源信息汇聚
            return predicted_center(player)  # 实时目标带提前量
        return intel.fresh_pos(now)          # 过期情报返回 None → 巡逻

    def track_progress(self, dt):
        """卡死检测：静止且未挪窝即累计；挪窝清零并留足迹（碰撞避免依据）"""
        cur = (self.gc, self.gr)
        if cur != self.last_cell:
            self.last_cell = cur
            self.trail.append(cur)
            del self.trail[:-8]
            self.stuck = 0.0
        elif not self.moving:
            self.stuck += dt

    def trail_fork(self, grid):
        """足迹回溯：最近经过的多出口分叉点（来路最可靠）"""
        for cell in reversed(self.trail):
            if cell != (self.gc, self.gr) and exit_count(grid, *cell) >= 3:
                return cell
        return None

    def escape_deadend(self, grid, blocked):
        """脱困三级策略：回溯分叉 → A* 改道最近开阔点 → 冷静期巡逻"""
        self.stuck, self.escapes = 0.0, self.escapes + 1
        if self.escapes > 3:
            self.calm, self.escapes = 2.0, 0
            LOG.info("AI 脱困失败, 进入 2s 战术冷静")
            self.patrol(grid, blocked)
            return
        goal = self.trail_fork(grid) or nearest_junction(grid, self.gc, self.gr)
        if goal:
            self.path = astar(grid, (self.gc, self.gr), goal) or []
            self.goal, self.repath = goal, self.repath_time
        if self.path and self.try_move(self.path[0][0] - self.gc,
                                       self.path[0][1] - self.gr, grid, blocked):
            self.path.pop(0)
        else:
            self.random_step(grid, blocked)

    def update_ai(self, dt, grid, tanks, blocked, intel, now):
        self.fire_cd = max(0, self.fire_cd - dt)
        self.grace = max(0, self.grace - dt)
        self.calm = max(0, self.calm - dt)
        if self.grace <= 0:
            self.try_fire()               # 定时开炮：节奏全权由冷却常量决定
        self.track_progress(dt)
        if self.grace > 0 or self.calm > 0:  # 开局缓冲/脱困冷静：先机动散开
            self.patrol(grid, blocked)
            return
        player = next(t for t in tanks if t.is_player)
        goal = self.acquire_goal(grid, player, intel, now)
        if self.stuck > 0.5 and goal:        # 追击途中被堵：脱困优先
            self.escape_deadend(grid, blocked)
            return
        if goal is None:
            self.patrol(grid, blocked)       # 情报过期 → 遗忘并巡逻
            return
        self.chase(dt, grid, goal[0], goal[1], blocked)

    def runway_free(self, grid, d, probe):
        """沿 d 方向探 probe 格的连续可走距离：迷宫走廊择向依据"""
        length, gc, gr = 0, self.gc + d[0], self.gr + d[1]
        while length < probe and can_stand(grid, gc, gr):
            length += 1
            gc += d[0]
            gr += d[1]
        return length

    def patrol(self, grid, blocked):
        """巡逻：沿最长走廊直行，尽头择向（迷宫友好且确定性不抖动）"""
        if self.moving:
            return
        if self.runway_free(grid, self.dir, 2) and \
                self.try_move(*self.dir, grid, blocked):
            return
        back = (-self.dir[0], -self.dir[1])
        best, best_len = None, -1
        for d in DIRS:
            if d == back:
                continue                    # 优先不回头
            length = self.runway_free(grid, d, 8)
            if length > best_len:
                best, best_len = d, length
        self.try_move(*(best or back), grid, blocked)

    def random_step(self, grid, blocked):
        # 固定顺序而非逐帧随机：被挡时朝向稳定，杜绝炮管高频抖动
        for d in (d for d in DIRS if d != self.dir):
            if self.try_move(*d, grid, blocked):
                return

    def chase(self, dt, grid, ax, ay, blocked):
        cx, cy = self.center()
        if abs(cx - ax) < 8 or abs(cy - ay) < 8:
            self.aim_and_fire(ax, ay)       # 对齐目标点：站桩开火，不再寻路
            return
        if self.moving:
            return
        self.follow_path(dt, grid, ax, ay, blocked)

    def aim_and_fire(self, ax, ay):
        """纯瞄准转向：开火节奏已移交 update_ai 的定时器，职责分离"""
        dx, dy = ax - self.px, ay - self.py
        if abs(dx) >= abs(dy):
            d = (1 if dx > 0 else -1, 0)
        else:
            d = (0, 1 if dy > 0 else -1)
        if not self.moving:
            self.dir = d                    # 转向仅允许在格点空闲时，保网格稳定
            self.sync_turret_to_body()

    def follow_path(self, dt, grid, ax, ay, blocked):
        self.repath -= dt
        goal = (int(ax // CELL), int(ay // CELL))   # 拦截：终点取目标所在格
        if not self.path or self.goal != goal or self.repath <= 0:
            self.goal = goal
            self.path = astar(grid, (self.gc, self.gr), goal) or []
            self.repath = self.repath_time
        if not self.path:
            if not self.greedy_step(grid, goal, blocked):
                self.random_step(grid, blocked)
            return
        nxt = self.path[0]
        if self.try_move(nxt[0] - self.gc, nxt[1] - self.gr, grid, blocked):
            self.path.pop(0)
        elif len(self.path) == 1:
            self.detour_step(grid, goal, blocked)   # 贴脸未对齐：确定性侧移
        else:
            self.path = []                   # 被坦克临时阻挡：下帧重算

    def greedy_step(self, grid, goal, blocked):
        """A* 无路时的兜底：沿误差主轴逼近目标"""
        dc = (goal[0] > self.gc) - (goal[0] < self.gc)
        dr = (goal[1] > self.gr) - (goal[1] < self.gr)
        if abs(goal[0] - self.gc) >= abs(goal[1] - self.gr):
            order = [(dc, 0), (0, dr)]
        else:
            order = [(0, dr), (dc, 0)]
        for d in order:
            if self.try_move(*d, grid, blocked):
                return True
        return False

    def detour_step(self, grid, goal, blocked):
        """贴脸被挡且未对齐：固定优先序侧移找射击线，避免逐帧乱转"""
        dx = (goal[0] > self.gc) - (goal[0] < self.gc)
        dy = (goal[1] > self.gr) - (goal[1] < self.gr)
        if dx == 0:
            order = [(0, dy or 1), (1, 0), (-1, 0)]
        elif dy == 0:
            order = [(dx or 1, 0), (0, 1), (0, -1)]
        else:
            order = [(0, dy), (dx, 0), (-dx, 0)]
        for d in order:
            if self.try_move(*d, grid, blocked):
                return


def predicted_center(t):
    """AI 预判点：目标移动中取其将到格中心（提前量），静止取当前中心"""
    if t.moving:
        return t.tx + 16, t.ty + 16
    return t.center()


# ---------------- 子弹与特效 ----------------
class Bullet:
    def __init__(self, owner, x, y, d):
        self.owner, self.x, self.y, self.d = owner, float(x), float(y), d
        self.bounced = False               # 光线式反弹仅允许一次
        self.portal_cd = 0.0               # 穿门冷却：防出入门格即回环

    def rect(self):
        return pygame.Rect(int(self.x) - 4, int(self.y) - 4, 8, 8)


class Explosion:
    LIFE = 0.35

    def __init__(self, x, y):
        self.x, self.y, self.t = x, y, self.LIFE


class Effects:
    def __init__(self, mode="normal", level=0, score=0):
        self.flash = 0.0
        self.mode = mode      # normal=普通模式 / endless=无尽模式
        self.level = level    # 无尽关卡号（普通模式恒 0）
        self.score = score    # 分数统计：击毁 AI +100，拆砖 +5（无尽跨关继承）
        self.nuke_used = False   # 核弹一局一次：用后锁到重开
        self.shift_at = -1e9     # 双击 Shift 确认窗口的时戳
        self.finale_t = 0.0      # 核弹结算连环引爆的节拍器
        self.finale_n = 0        # 余爆轮数上限：三轮后归于死寂
        self.pending_music = None  # 待接力曲目 (剩余秒, 音量, 播曲函数)
        self.coin_gain = 0         # 战败结算兑出的金币数（ELOSE 画面展示用）
        self.gear_toast = ("", 0.0)  # 补给生效提示 (文案, 剩余秒)


# ---------------- 音效：纯代码合成 PCM 波形，零外部文件 ----------------
def _synth(f0, f1, ms, vol, kind):
    """按混音器真实采样率合成 int16 单声道波形，避免播放变调"""
    rate = pygame.mixer.get_init()[0]
    n = int(rate * ms / 1000)
    out = array.array("h", bytes(2 * n))
    phase = 0.0
    for i in range(n):
        t = i / max(1, n - 1)
        phase += 2 * math.pi * (f0 + (f1 - f0) * t) / rate
        if kind == "noise":
            v = random.uniform(-1, 1) * (1 - t)
        elif kind == "sine":
            v = math.sin(phase) * (1 - t)
        else:
            v = (1 if math.sin(phase) >= 0 else -1) * (1 - t)
        out[i] = int(v * vol * 32767)
    return out.tobytes()


def _wrap_channels(mono):
    """混音器为立体声时交错复制为双声道，保证字节格式匹配"""
    if pygame.mixer.get_init()[2] == 2:
        samples = array.array("h")
        samples.frombytes(mono)
        stereo = array.array("h", bytes(4 * len(samples)))
        stereo[0::2] = samples
        stereo[1::2] = samples
        return stereo.tobytes()
    return mono


def init_sounds():
    """合成全部音效；任何失败直接静音降级，绝不影响游戏运行"""
    try:
        if not pygame.mixer.get_init():
            LOG.warning("混音器不可用，静音运行")
            return
        specs = {
            "shoot": (700, 200, 90, 0.35, "square"),    # 发射：下滑方波
            "brick": (0, 0, 70, 0.30, "noise"),         # 拆砖：闷响
            "steel": (1300, 1300, 60, 0.25, "sine"),    # 打钢：金属叮
            "explode": (0, 0, 320, 0.45, "noise"),      # 敌坦克爆炸
            "die": (300, 60, 400, 0.45, "square"),      # 玩家阵亡：低鸣
            "move": (150, 120, 55, 0.10, "square"),     # 移动：轻马达声
            "turn": (950, 620, 40, 0.12, "square"),     # 炮塔旋转：短促咔哒
            "portal": (380, 1200, 180, 0.25, "sine"),   # 传送门：上滑呜鸣
        }
        for name, args in specs.items():
            SOUNDS[name] = pygame.mixer.Sound(buffer=_wrap_channels(_synth(*args)))
        LOG.info("音效合成完成: %d 个", len(SOUNDS))
    except Exception as e:
        SOUNDS.clear()
        LOG.warning("音效合成失败，静音运行: %s", e)


def play_sound(name, volume=None):
    """volume 仅作用于本次通道：局部降音量而不污染全局同名音效"""
    snd = SOUNDS.get(name)
    if snd:
        ch = snd.play()
        if volume is not None and ch:
            ch.set_volume(volume)


def play_win_music(volume=1.0):
    """胜利结算曲：内嵌 mp3 惰性解码（仅胜利瞬间），任何失败静音降级"""
