def play_suicide():
    """核弹台词「自刎归天」：返回时长供爆炸/结算曲延迟对齐；失败降级 0"""
    try:
        snd = pygame.mixer.Sound(io.BytesIO(base64.b64decode(SUICIDE_B64)))
        snd.set_volume(0.9)
        snd.play()
        LOG.info("核弹台词播放: 自刎归天 %.1fs", snd.get_length())
        return snd.get_length()
    except Exception as e:
        LOG.warning("核弹台词播放失败, 静音降级: %s", e)
        return 0.0


def overlapped_cells(rect):
    pts = ((rect.left + 1, rect.top + 1), (rect.right - 1, rect.top + 1),
           (rect.left + 1, rect.bottom - 1), (rect.right - 1, rect.bottom - 1))
    return {(x // CELL, y // CELL) for x, y in pts}


def settle_bounce(b, c, r):
    """首次撞墙：按命中面法线做镜面反射并贴回墙外；已反弹过则消失"""
    if b.bounced:
        return "die"
    b.bounced = True
    wall_cx, wall_cy = c * CELL + CELL / 2, r * CELL + CELL / 2
    if abs(b.x - wall_cx) > abs(b.y - wall_cy):   # 命中左/右面：翻转 x 分量
        b.x = c * CELL - 5 if b.x < wall_cx else (c + 1) * CELL + 5
        b.d = (-b.d[0], b.d[1])
    else:                                          # 命中顶/底面：翻转 y 分量
        b.y = r * CELL - 5 if b.y < wall_cy else (r + 1) * CELL + 5
        b.d = (b.d[0], -b.d[1])
    return "bounce"


def hit_wall(b, grid, fx):
    """砖被炸开、钢无损、基地穿越；返回 die/bounce/None 由调用方处置"""
    for c, r in overlapped_cells(b.rect()):
        if not in_bounds(c, r):
            continue
        if grid[r][c] == BRICK:
            grid[r][c] = EMPTY
            clear_map_cell(r, c)             # 静态缓存层同步：只擦该格
            play_sound("brick")
            fx.score += 5
            return settle_bounce(b, c, r)
        if grid[r][c] == STEEL:
            play_sound("steel")
            return settle_bounce(b, c, r)
    return None


def apply_damage(t, dmg, fx):
    """统一伤害结算：任意来源弹丸对任意类型坦克等量扣血，归零才走摧毁链路"""
    t.hp -= dmg
    LOG.info("伤害结算: %s坦克 -%d 剩余 %d", "玩家" if t.is_player else "AI",
             dmg, max(0, t.hp))
    if t.hp <= 0:
        destroy_tank(t, fx)


def hit_tank(b, tanks, fx):
    for t in tanks:
        if not t.alive:
            continue
        if not b.owner.is_player and t is b.owner:
            continue                        # AI 不自伤：出膛弹跳过自身碰撞盒
        if not t.is_player and not b.owner.is_player:
            continue                        # AI 阵营无内讧：AI 弹穿过 AI 不结算
        if t.is_player and t.invincible > 0:
            continue                        # 无敌帧：重生保护期弹丸穿过不结算
        if b.rect().colliderect(t.rect()):
            apply_damage(t, BULLET_DAMAGE, fx)   # 玩家弹对玩家自己+AI 一律生效
            return True                    # 命中任意坦克：弹丸即消耗
    return False


def destroy_tank(t, fx):
    EXPLOSIONS.append(Explosion(*t.center()))
    t.alive = False
    t.moving = False
    if t.is_player:
        t.lives -= 1
        t.respawn = RESPAWN_DELAY
        fx.flash = 0.35                     # 被击中屏幕闪红提示
        play_sound("die")
        LOG.info("玩家被击毁, 剩余生命 %d", t.lives)
    else:
        fx.score += 100                     # 击毁敌方坦克计分
        play_sound("explode")
        LOG.info("敌方坦克阵亡, 当前总分 %d", fx.score)


def update_bullet(b, dt, grid, tanks, fx):
    dist = BULLET_SPEED * dt
    steps = max(1, int(dist // 4) + 1)     # 子步<4px：斜向弹擦墙角时不隧穿
    b.portal_cd = max(0.0, b.portal_cd - dt)
    for _ in range(steps):
        b.x += b.d[0] * dist / steps
        b.y += b.d[1] * dist / steps
        if not (0 <= b.x < MAP_PX and 0 <= b.y < MAP_PX):
            return False                   # 出界即消失；边界=战场尺寸（无尽随关卡扩大）
        result = hit_wall(b, grid, fx)
        if result == "die":
            return False
        if result == "bounce":
            return True                    # 反弹帧跳过坦克判定，下帧正常飞
        if hit_tank(b, tanks, fx):
            return False
        dest = PORTAL_MAP.get((int(b.x) // CELL, int(b.y) // CELL))
        if dest is not None and b.portal_cd <= 0:
            b.x, b.y = dest[0] * CELL + 16, dest[1] * CELL + 16
            b.portal_cd = PORTAL_BULLET_CD    # 弹心入格即穿：方向不变续飞
            play_sound("portal")
    return True


def update_explosions(dt):
    for e in EXPLOSIONS:
        e.t -= dt
    EXPLOSIONS[:] = [e for e in EXPLOSIONS if e.t > 0]


# ---------------- 玩家逻辑 ----------------
KEYMAP = ((pygame.K_UP, (0, -1)), (pygame.K_DOWN, (0, 1)),
          (pygame.K_LEFT, (-1, 0)), (pygame.K_RIGHT, (1, 0)),
          (pygame.K_w, (0, -1)), (pygame.K_s, (0, 1)),
          (pygame.K_a, (-1, 0)), (pygame.K_d, (1, 0)))


KEY_TO_DIR = dict(KEYMAP)


class InputState:
    """按按下顺序记录方向键：后按优先，组合键不打架，转向跟手"""

    def __init__(self):
        self.keys = []

    def press(self, key):
        if key in KEY_TO_DIR and key not in self.keys:
            self.keys.append(key)

    def release(self, key):
        if key in self.keys:
            self.keys.remove(key)

    def direction(self):
        return KEY_TO_DIR[self.keys[-1]] if self.keys else None

    def clear(self):
        self.keys.clear()


def respawn_player(p):
    p.gc, p.gr = PLAYER_SPAWN
    p.px, p.py = PLAYER_SPAWN[0] * CELL, PLAYER_SPAWN[1] * CELL
    p.dir = (0, -1)
    p.turret, p.turret_deg = 0, 0.0         # 重生炮塔回正：与车体朝向一致
    p.moving = False
    p.alive = True
    p.invincible = INVINCIBLE_TIME
    p.hp = p.HP                            # 重生满血：与新伤害机制配套


def update_player(p, dt, inputs, grid):
    p.invincible = max(0, p.invincible - dt)
    p.fire_cd = max(0, p.fire_cd - dt)
    if not p.alive:
        if p.lives > 0:                     # 还有命：延迟 1 秒基地原位重生
            p.respawn -= dt
            if p.respawn <= 0:
                respawn_player(p)
        return
    if p.moving:
        return
    d = inputs.direction()
    if d:
        # 坦克可互穿：障碍集留空，仅地形（砖/钢/边界）阻挡
        if p.try_move(*d, grid, frozenset()):
            play_sound("move")              # 移动反馈：短促马达声


# ---------------- 绘制 ----------------
def load_background():
    """解码 Base64 内置底图并压暗；任何失败降级深色背景（失败兜底）"""
    surf = pygame.Surface((SCREEN_W, SCREEN_H))
    surf.fill((24, 28, 24))
    try:
        if BG_B64:
            img = pygame.image.load(io.BytesIO(base64.b64decode(BG_B64))).convert()
            surf.blit(pygame.transform.scale(img, (SCREEN_W, SCREEN_H)), (0, 0))
            LOG.info("内置底图加载成功: %.0f KB", len(BG_B64) * 3 / 4096)
        else:
            LOG.warning("未内嵌底图，使用纯色背景")
        shade = pygame.Surface((SCREEN_W, SCREEN_H))
        shade.set_alpha(115)                # 压暗底图，保证墙/坦克可读性
        surf.blit(shade, (0, 0))
    except Exception as e:
        LOG.warning("底图解码失败，降级纯色背景: %s", e)
    return surf


BRICK_COLOR, BRICK_DARK = (172, 74, 52), (120, 46, 34)
STEEL_COLOR, STEEL_DARK = (185, 190, 200), (118, 124, 134)
GRASS_COLOR, GRASS_DARK = (96, 148, 62), (66, 112, 42)
GRASS_SURF = None       # 草坪顶层缓存：压在坦克之上实现隐身，随关重建


def cell_rect(c, r):
    """格 → 屏幕像素矩形：取整对齐相邻格，杜绝缩放缝隙"""
    cs = CELL * VIEW_SCALE
    x, y = round(c * cs), round(r * cs)
    return (x, y, round((c + 1) * cs) - x, round((r + 1) * cs) - y)


def build_map_surf(grid):
    """静态层整图缓存：砖/钢一次绘制进缓存面，拆砖只擦对应格"""
    surf = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
    s = VIEW_SCALE
    for r in range(GRID):
        for c in range(GRID):
            x, y, w, h = cell_rect(c, r)
            if grid[r][c] == BRICK:
                surf.fill(BRICK_COLOR, (x, y, w, h))
                surf.fill(BRICK_DARK, (x + max(1, int(2 * s)), y + int(6 * s),
                                       max(1, w - int(4 * s)), max(1, int(3 * s))))
                surf.fill(BRICK_DARK, (x + max(1, int(2 * s)), y + int(22 * s),
                                       max(1, w - int(4 * s)), max(1, int(3 * s))))
            elif grid[r][c] == STEEL:
                surf.fill(STEEL_DARK, (x, y, w, h))
                inset = max(1, int(4 * s))
                surf.fill(STEEL_COLOR, (x + inset, y + inset,
                                        max(1, w - 2 * inset), max(1, h - 2 * inset)))
    return surf


def clear_map_cell(r, c):
    """拆砖同步缓存层：只擦该格，整图不重绘"""
    if MAP_SURF is not None:
        MAP_SURF.fill((0, 0, 0, 0), cell_rect(c, r))


def build_grass_surf(grid):
    """草坪顶层：盖在坦克之上即隐身；草叶纹理两道深色竖痕"""
    surf = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
    s = VIEW_SCALE
    for r in range(GRID):
        for c in range(GRID):
            if grid[r][c] != GRASS:
                continue
            x, y, w, h = cell_rect(c, r)
            surf.fill(GRASS_COLOR, (x, y, w, h))
            blade = max(1, int(2 * s))
            for ox in (int(10 * s), w - int(10 * s)):
                for oy in (int(8 * s), int(20 * s)):
                    pygame.draw.line(surf, GRASS_DARK,
                                     (x + ox, y + oy), (x + ox, y + oy + int(6 * s)),
                                     blade)
    return surf


def draw_map(screen, grid):
    global MAP_SURF, GRASS_SURF
    if MAP_SURF is None:
        MAP_SURF = build_map_surf(grid)
        GRASS_SURF = build_grass_surf(grid)
    screen.blit(MAP_SURF, (0, 0))


def tank_in_grass(t, grid):
    """隐身判定：车身 2x2 任一格是草坪即算入草"""
    return any(in_bounds(c, r) and grid[r][c] == GRASS
               for c, r in overlapped_cells(t.rect()))


def draw_grass_layer(screen, grid, player):
    """草坪覆盖层：敌我坦克一律盖住；玩家半透明重绘防迷路"""
    if GRASS_SURF is None:
        return
    screen.blit(GRASS_SURF, (0, 0))
    if not (player.alive and tank_in_grass(player, grid)):
        return
    size = max(8, int(round(32 * VIEW_SCALE)))
    ghost = tank_sprite(player, size).copy()
    ghost.set_alpha(115)                  # 幽灵显形：玩家不至于找不到自己
    center = (int((player.px + 16) * VIEW_SCALE),
              int((player.py + 16) * VIEW_SCALE))
    screen.blit(ghost, ghost.get_rect(center=center))
    draw_barrel(screen, player)           # 炮杆保留：瞄准反馈不丢失


def draw_base(screen):
    """基地老鹰：金色鹰形（1 格大小配 1 格车身），随视图等比缩放"""
    s = VIEW_SCALE
    x, y = PLAYER_SPAWN[0] * CELL * s, PLAYER_SPAWN[1] * CELL * s
    screen.fill((96, 80, 44), (x, y, 32 * s, 32 * s))
    pts = ((16, 4), (6, 15), (11, 15), (11, 26), (21, 26), (21, 15), (26, 15))
    pygame.draw.polygon(screen, (240, 200, 60),
                        [(x + px * s, y + py * s) for px, py in pts])


def draw_portals(screen):
    """传送门绘制：同对同色双环呼吸脉动，颜色即配对关系"""
    t_ms = pygame.time.get_ticks()
    for i, (a, b) in enumerate(PORTAL_PAIRS):
        color = PORTAL_COLORS[i % len(PORTAL_COLORS)]
        for c, r in (a, b):
            x = int((c * CELL + 16) * VIEW_SCALE)
            y = int((r * CELL + 16) * VIEW_SCALE)
            pulse = 0.5 + 0.5 * math.sin(t_ms / 260 + c * 2 + r)
            outer = max(3, int(13 * VIEW_SCALE))
            pygame.draw.circle(screen, color, (x, y), outer,
                               max(1, int(2 * VIEW_SCALE)))
            inner = max(2, int((4 + 5 * pulse) * VIEW_SCALE))
            pygame.draw.circle(screen, color, (x, y), inner)


DIR_ANGLE = {(0, -1): 0, (1, 0): 270, (0, 1): 180, (-1, 0): 90}
_OX_CACHE = {}          # 木牛流马朝上图层缓存：同色只建一次


def build_ox_surface(body_color, horns):
    """朝上 64px 木牛流马：木箱粮车 + 牛头双角 + 双木轮 + 横向木纹"""
    key = (body_color, horns)
    if key in _OX_CACHE:
        return _OX_CACHE[key]
    surf = pygame.Surface((64, 64), pygame.SRCALPHA)
    pygame.draw.rect(surf, WOOD_DARK, (8, 50, 12, 10), border_radius=3)   # 左轮
    pygame.draw.rect(surf, WOOD_DARK, (44, 50, 12, 10), border_radius=3)  # 右轮
    pygame.draw.rect(surf, body_color, (12, 18, 40, 36), border_radius=6)
    dark = tuple(ch // 2 for ch in body_color)
    pygame.draw.line(surf, dark, (14, 30), (50, 30), 2)                   # 木纹
    pygame.draw.line(surf, dark, (14, 42), (50, 42), 2)
    draw_ox_head(surf, OX_BROWN, horns)
    _OX_CACHE[key] = surf
    return surf


_SPRITE_CACHE = {}       # (阵营, 朝向, 尺寸) → 已旋转贴图，同参只旋转一次


def _autocrop(surf):
    """裁掉透明边框并回填正方形：旋转中心恒为几何中心"""
    w, h = surf.get_size()
    x0, y0, x1, y1 = w, h, 0, 0
    for x in range(w):
        for y in range(h):
            if surf.get_at((x, y)).a > 24:
                x0, y0 = min(x0, x), min(y0, y)
                x1, y1 = max(x1, x), max(y1, y)
    if x1 < x0 or y1 < y0:
        return None
    crop = surf.subsurface((x0, y0, x1 - x0 + 1, y1 - y0 + 1)).copy()
    side = max(crop.get_size())
    out = pygame.Surface((side, side), pygame.SRCALPHA)
    out.blit(crop, ((side - crop.get_width()) // 2,
                    (side - crop.get_height()) // 2))
    return out


def load_sprite(path):
    """外贴图加载：缩至 256 → 四角取色抠底 → 裁边；任一步失败回退矢量"""
    try:
        img = pygame.image.load(path).convert()
        img = pygame.transform.smoothscale(img, (256, 256))
        pts = ((1, 1), (254, 1), (1, 254), (254, 254))
        corners = [tuple(img.get_at(p))[:3] for p in pts]   # Color 不可哈希,转元组
        bg = max(set(corners), key=corners.count)
        out = img.convert_alpha()
        tol2 = 90 * 90                     # 容差吸掉 JPG 边缘噪点
        for x in range(256):
            for y in range(256):
                c = out.get_at((x, y))
                if (c[0] - bg[0]) ** 2 + (c[1] - bg[1]) ** 2 + (c[2] - bg[2]) ** 2 <= tol2:
                    out.set_at((x, y), (0, 0, 0, 0))
        return _autocrop(out)
    except Exception as e:
        LOG.warning("贴图加载失败(%s): %s", os.path.basename(path), e)
        return None


def init_textures():
    """外贴图装配：player/enemy 两张，缺图静默回退矢量模型不阻断启动"""
    for name, fname in (("player", "player_ox.jpg"), ("enemy", "enemy_horse.jpg")):
        TEXTURES[name] = load_sprite(os.path.join(ASSET_DIR, fname))
        LOG.info("外贴图 %s: %s", name, "就绪" if TEXTURES[name] else "缺失, 回退矢量")


def tank_base_surface(t, size):
    """朝上基础图：外贴图优先，缺失回退矢量木牛流马"""
    tex = TEXTURES.get("player" if t.is_player else "enemy")
    if tex is not None:
        return pygame.transform.smoothscale(tex, (size, size))
    horns = WOOD_DARK if t.is_player else (120, 40, 32)
    return pygame.transform.smoothscale(build_ox_surface(t.color, horns), (size, size))


def tank_sprite(t, size):
    """取当前朝向贴图：同(阵营,朝向,尺寸)只旋转一次"""
    key = (t.is_player, t.dir, size)
    if key not in _SPRITE_CACHE:
        _SPRITE_CACHE[key] = pygame.transform.rotate(
            tank_base_surface(t, size), DIR_ANGLE[t.dir])
    return _SPRITE_CACHE[key]


def draw_tank(screen, t):
    """木牛流马绘制：外贴图随行进方向旋转，碰撞体仍恒为 2x2 格"""
    if not t.alive:
        return
    if t.is_player and t.invincible > 0 and int(t.invincible * 10) % 2 == 0:
        return                              # 无敌帧：高频闪烁提示
    size = max(8, int(round(32 * VIEW_SCALE)))
    sprite = tank_sprite(t, size)
    center = (int((t.px + 16) * VIEW_SCALE), int((t.py + 16) * VIEW_SCALE))
    screen.blit(sprite, sprite.get_rect(center=center))
    draw_barrel(screen, t)


def draw_barrel(screen, t):
    """木臂投石杆随炮塔角度旋转，随视图等比缩放"""
    barrel = pygame.Surface((8, 40), pygame.SRCALPHA)
    barrel.fill(WOOD_DARK, (0, 2, 8, 18))   # 以中心为轴向上伸出 18px（配 1 格车身）
    rot = pygame.transform.rotate(barrel, -t.turret_deg)  # deg 顺时针为正
    if VIEW_SCALE < 1.0:
        rot = pygame.transform.smoothscale(
            rot, (max(2, int(rot.get_width() * VIEW_SCALE)),
                  max(2, int(rot.get_height() * VIEW_SCALE))))
    center = (int((t.px + 16) * VIEW_SCALE), int((t.py + 16) * VIEW_SCALE))
    screen.blit(rot, rot.get_rect(center=center))


def draw_panel(screen, text, font, y, right=False, color=(255, 255, 255)):
    """信息条：半透明深底 + 细描边，数值面板传金色"""
    w = font.size(text)[0] + 16
    x = SCREEN_W - w - 8 if right else 8
    bar = pygame.Surface((w, 22), pygame.SRCALPHA)
    bar.fill((8, 8, 12, 175))
    screen.blit(bar, (x, y))
    pygame.draw.rect(screen, (72, 72, 84), (x, y, w, 22), 1)
    screen.blit(font.render(text, True, color), (x + 8, y + 4))


def draw_skill_bar(screen, font):
    """技能栏（参考 _drawSkillBar）：底部圆形图标 + 冷却扇形 + 就绪高亮 + F 键提示"""
    unlocked = [cfg for cfg in SKILLS if cfg["id"] in PLAYER_SKILLS]
    if not unlocked:
        return
    y = SCREEN_H - 64
    cx = SCREEN_W // 2 - (len(unlocked) - 1) * 46
    for i, cfg in enumerate(unlocked):
        st = PLAYER_SKILLS[cfg["id"]]
        x = cx + i * 92
        ready = st["cd"] <= 0
        deny = pygame.time.get_ticks() - _SKILL_DENY["ts"] < 200
        color = GOLD if ready else TEXT_WARN if deny else GRAY_TXT
        pygame.draw.circle(screen, (24, 28, 19), (x, y), 27)
        pygame.draw.circle(screen, color, (x, y), 27, 2)
        if not ready:                      # 冷却弧线：剩余比例的顺时针进度环
            frac = st["cd"] / cfg["cd"]
            pygame.draw.arc(screen, TEXT_WARN, (x - 24, y - 24, 48, 48),
                            -math.pi / 2, -math.pi / 2 + math.pi * 2 * frac, 4)
        icon = ui_font(22).render(cfg["name"][0], True,
                                  TEXT_MAIN if ready else GRAY_TXT)
        screen.blit(icon, icon.get_rect(center=(x, y - 2)))
        cd_txt = "就绪" if ready else f"{st['cd']:.0f}s"
        tip = ui_font(13).render(cd_txt, True, GOLD if ready else GRAY_TXT)
        screen.blit(tip, tip.get_rect(center=(x, y + 40)))


def draw_hud(screen, font, player, ais, fx):
    # 左上角：题目指定文案的操作说明 + YXF 身份标识（加分项3）+ 炮塔旋转提示
    draw_panel(screen, "操作说明：方向键移动，空格发射", font, 6)
    screen.blit(font.render("YXF", True, (255, 210, 60)), (8, 30))
    draw_panel(screen, "Q/E 旋转炮塔（8 向）· F 技能", font, 52)
    nuke_state = "已用" if fx.nuke_used else "待命"
    draw_panel(screen, f"Shift×2 核弹 [{nuke_state}]", font, 74)
    if fx.mode == "endless":
        draw_panel(screen, f"无尽模式 第 {fx.level} 关", font, 96)
    # 右上角：生命/血量 白字，敌人/分数/金币 金字（数值归组一眼可辨）
    enemies = sum(a.alive for a in ais)
    draw_panel(screen, f"生命 {player.lives}   血量 {max(0, player.hp)}",
               font, 6, right=True)         # max(0,·)：死亡瞬间 hp 为负，HUD 不显示负数
    draw_panel(screen, f"敌人 {enemies}   分数 {fx.score}", font, 30, right=True,
               color=GOLD)
    if fx.mode == "endless":               # 金币归入右侧数据卡组：战利品语义
        draw_panel(screen, f"金币 {WALLET.coins}", font, 54, right=True, color=GOLD)
    draw_skill_bar(screen, font)


def center_text(screen, font, text, color, y=None):
    surf = font.render(text, True, color)
    cy = SCREEN_H // 2 if y is None else y
    screen.blit(surf, surf.get_rect(center=(SCREEN_W // 2, cy)))


def draw_nuke_panel(screen):
    """结算底板：暗幕压场 + 呼吸描边双层面板（毫秒时钟驱动，结算态仍会脉动）"""
    veil = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
    veil.fill((12, 6, 4, 178))
    screen.blit(veil, (0, 0))
    panel = pygame.Rect(0, 0, 640, 300)
    panel.center = (SCREEN_W // 2, SCREEN_H // 2)
    pulse = 0.5 + 0.5 * math.sin(pygame.time.get_ticks() / 320)
    glow = (int(200 + 55 * pulse), int(84 + 40 * pulse), 32)
    pygame.draw.rect(screen, (26, 16, 10), panel, border_radius=16)
    pygame.draw.rect(screen, glow, panel, 4, border_radius=16)
    pygame.draw.rect(screen, (120, 80, 40), panel.inflate(-18, -18), 1,
                     border_radius=12)
    return panel


def draw_nuke_finale(screen, win_font, font):
    """核弹结算文案：底板之上铺三级层次（标题 / 分割线 / 双行副文案）"""
    panel = draw_nuke_panel(screen)
    center_text(screen, win_font, "你赢了，但代价是什么呢", (255, 200, 90),
                panel.top + 76)
    pygame.draw.line(screen, (160, 110, 50), (panel.left + 70, panel.top + 126),
                     (panel.right - 70, panel.top + 126), 2)
    center_text(screen, font, "战术核弹的余波散尽，战场归于死寂", (222, 202, 172),
                panel.top + 168)
    center_text(screen, font, "本局禁止 R 重开（重启程序可再战）", (255, 160, 120),
                panel.top + 212)


def draw_result_veil(screen):
    """结算底板：暗幕 + 居中面板，四种结局共用同一视觉语言"""
    veil = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
    veil.fill((8, 8, 12, 168))
    screen.blit(veil, (0, 0))
    panel = pygame.Rect(0, 0, 620, 286)
    panel.center = (SCREEN_W // 2, SCREEN_H // 2)
    pygame.draw.rect(screen, BG_PANEL, panel, border_radius=14)
    pygame.draw.rect(screen, BORDER_BASE, panel, 2, border_radius=14)
    return panel


def draw_finale_divider(screen, y):
    """结算分割线：240px 金线，标题与副文案的节奏锚点"""
    pygame.draw.line(screen, GOLD_DIM, (SCREEN_W // 2 - 120, y),
                     (SCREEN_W // 2 + 120, y), 2)


def render(screen, bg, grid, player, ais, fx, font, big_font, win_font,
           menu_font, flash_surf, state):
    screen.blit(bg, (0, 0))
    draw_map(screen, grid)
    draw_base(screen)
    draw_portals(screen)
    for t in [player] + ais:
        draw_tank(screen, t)
    draw_grass_layer(screen, grid, player)
    for b in BULLETS:
        rect = b.rect()
        size = max(2, int(8 * VIEW_SCALE))
        screen.fill((255, 230, 90), (int(rect.x * VIEW_SCALE),
                                     int(rect.y * VIEW_SCALE), size, size))
    for e in EXPLOSIONS:
        k = 1 - e.t / Explosion.LIFE
        pos = (int(e.x * VIEW_SCALE), int(e.y * VIEW_SCALE))
        pygame.draw.circle(screen, (255, 170, 60), pos,
                           max(1, int((6 + 26 * k) * VIEW_SCALE)))
    draw_hud(screen, font, player, ais, fx)
    msg, ttl = fx.gear_toast              # 补给生效横幅：开局 3 秒金色置顶
    if ttl > 0:
        center_text(screen, ui_font(22), msg, GOLD, 128)
    if fx.flash > 0:
        flash_surf.set_alpha(min(255, int(130 * fx.flash / 0.35)))
        screen.blit(flash_surf, (0, 0))
    if state in ("WIN", "LOSE", "CLEAR", "ELOSE"):
        draw_result_veil(screen)
    if state == "WIN":
        center_text(screen, big_font, "旗开得胜！", GOLD, 340)
        draw_finale_divider(screen, 386)
        center_text(screen, menu_font, "真是一场酣畅淋漓的战斗啊",
                    TEXT_MAIN, 424)
    elif state == "WIN_NUKE":
        draw_nuke_finale(screen, win_font, menu_font)
    elif state == "LOSE":
        center_text(screen, big_font, "Game Over!", (230, 60, 60), 340)
        draw_finale_divider(screen, 386)
    elif state == "CLEAR":
        center_text(screen, big_font, f"第 {fx.level} 关 完成！", GOLD, 340)
        draw_finale_divider(screen, 386)
        center_text(screen, menu_font, "R - 下一关    ESC - 退出无尽模式",
                    TEXT_MAIN, 424)
        if fx.nuke_used:                    # 本关核弹通关：惩罚明示（HUD 分数同步）
            center_text(screen, menu_font,
                        f"核弹惩罚 -{NUKE_PENALTY} · 当前积分 {fx.score}",
                        TEXT_WARN, 462)
    elif state == "ELOSE":
        center_text(screen, win_font, f"无尽模式 · 止步第 {fx.level} 关", (230, 60, 60), 340)
        draw_finale_divider(screen, 386)
        center_text(screen, menu_font, "《关羽之歌》已为您奏响    ESC - 返回主菜单",
                    TEXT_MAIN, 424)
        if fx.coin_gain:
            center_text(screen, menu_font,
                        f"战败结算 +{fx.coin_gain} 金币（积分已进位兑换）· 总金币 {WALLET.coins}",
                        GOLD, 462)
    if state in ("WIN", "LOSE"):
        center_text(screen, menu_font, "R - 再来一次    ESC - 退出",
                    TEXT_MAIN, 500)
    pygame.display.flip()


# ---------------- 主菜单与操作说明 ----------------
# 军绿战术色板：橄榄深底 + 卡其军黄 + 暗棕硬影（迷彩军械风）
# 对比度经 WCAG 公式验证全部 ≥4.5:1，禁止肉眼调色后不再复算
BG_DARK = (18, 22, 15)           # 主底：橄榄深
BG_PANEL = (24, 30, 20)          # 面板底板
GOLD = (232, 204, 112)           # 主金 7.1:1（原 214,187,98 提亮）
GOLD_DIM = (180, 152, 78)        # 暗金：边框/分割线
RED_ACCENT = (82, 66, 38)        # 复古硬阴影
GRAY_TXT = (168, 176, 148)       # 副文字 5.8:1（原 136,142,122 提亮）
TEXT_MAIN = (226, 232, 214)      # 主文字 8.3:1
TEXT_WARN = (236, 110, 84)       # 警示/售罄/失败
TEXT_SUCCESS = (146, 210, 94)    # 购买成功
BORDER_BASE = (62, 70, 54)       # 通用描边
WOOD_DARK = (86, 64, 38)         # 深木色：木纹/牛角/木轮
OX_BROWN = (150, 112, 62)        # 原木色：牛头/装饰
MENU_BUTTONS = ("无尽模式", "普通模式", "军械商城", "操作说明")

_MENU_ANIM = {"sel": -1, "ts": 0}     # 菜单切换动画：选中项索引与切换时刻
_SHOP_FLASH = {"ts": 0, "ok": False}  # 商城购买成功绿闪：100ms 即逝
_UI_FONTS = {}                        # UI 字体缓存：按字号惰性建一次全程复用


def ui_font(size):
    """菜单态字体惰性缓存（沿用 _SCANLINES 惯例）：杜绝每帧新建 Font"""
    f = _UI_FONTS.get(size)
    if f is None:
        f = _UI_FONTS[size] = load_cjk_font(size)
    return f

