HELP_HEADS = ("普通模式", "无尽模式", "商城：")   # 章节头：金竖条锚点


def draw_help(screen, menu_font):
    """说明页：章节金竖条锚点 + 36px 均匀行高（空行恰半行）+ 超宽熔断"""
    screen.fill(BG_DARK)
    retro_text(screen, menu_font, "— 操作说明 —", GOLD, RED_ACCENT,
               (SCREEN_W // 2, 84), 3)
    panel = pygame.Rect(55, 128, 690, 652)
    pygame.draw.rect(screen, BG_PANEL, panel, border_radius=12)
    pygame.draw.rect(screen, BORDER_BASE, panel, 2, border_radius=12)
    y = 148
    for line in HELP_LINES:
        if not line:
            y += 18                        # 空行 = 半行高：段落节奏均匀
            continue
        head = line.startswith(HELP_HEADS)
        color = GOLD if head else GRAY_TXT if line.startswith("任意键") else TEXT_MAIN
        surf = menu_font.render(line, True, color)
        if surf.get_width() > 630:         # 熔断留痕：文案再长也只告警不出框
            LOG.warning("说明行超宽 %dpx: %s", surf.get_width(), line[:18])
        if head:                           # 章节头：4px 金竖条视觉锚点
            pygame.draw.rect(screen, GOLD, (67, y + 5, 4, 22), border_radius=2)
        screen.blit(surf, (79, y))
        y += 36                            # 行高 36：800px 屏 18 行的物理最优
    draw_scanlines(screen)


def skill_card_rects():
    """技能卡几何（参考 .form-card 三联排）：210x150"""
    return [pygame.Rect(55 + i * 240, 200, 210, 150)
            for i in range(len(SKILLS))]


def shop_rows():
    """补给行几何：三行大点击区（技能区下方）"""
    return [pygame.Rect(90, 414 + i * 72, 620, 64)
            for i in range(len(SHOP_ITEMS))]


def shop_purchase(idx):
    """统一购买入口：0-2 技能卡（永久解锁）/ 3-5 补给行（消耗品）"""
    if idx < len(SKILLS):
        return buy_skill(idx)
    return try_purchase(idx - len(SKILLS))


def shop_hit(pos):
    """命中检测：返回 (区索引, rect)；未命中 (None, None)"""
    for i, rect in enumerate(skill_card_rects()):
        if rect.collidepoint(pos):
            return i, rect
    for i, rect in enumerate(shop_rows()):
        if rect.collidepoint(pos):
            return i + len(SKILLS), rect
    return None, None


def draw_skill_card(screen, cfg, rect, active):
    """技能卡：圆形图标 + 名称 + 描述 + 价格/已解锁（军械库货架风）"""
    owned = cfg["id"] in PLAYER_SKILLS
    pygame.draw.rect(screen, (34, 40, 26) if active else (24, 28, 19),
                     rect, border_radius=14)
    border = GOLD_DIM if active and not owned else \
        TEXT_SUCCESS if owned else BORDER_BASE
    pygame.draw.rect(screen, border, rect, 2, border_radius=14)
    cx = rect.centerx
    pygame.draw.circle(screen, (24, 28, 19), (cx, rect.top + 38), 24)
    pygame.draw.circle(screen, GOLD if not owned else TEXT_SUCCESS,
                       (cx, rect.top + 38), 24, 2)
    icon = ui_font(24).render(cfg["name"][0], True, TEXT_MAIN)
    screen.blit(icon, icon.get_rect(center=(cx, rect.top + 38)))
    name = ui_font(20).render(cfg["name"], True, TEXT_MAIN)
    screen.blit(name, name.get_rect(center=(cx, rect.top + 76)))
    desc = ui_font(14).render(cfg["desc"][:12], True, GRAY_TXT)
    screen.blit(desc, desc.get_rect(center=(cx, rect.top + 102)))
    desc2 = ui_font(14).render(cfg["desc"][12:], True, GRAY_TXT)
    screen.blit(desc2, desc2.get_rect(center=(cx, rect.top + 120)))
    foot = "✓ 已解锁" if owned else f"{cfg['price']} 币"
    foot_surf = ui_font(17).render(foot, True,
                                  TEXT_SUCCESS if owned else GOLD)
    screen.blit(foot_surf, foot_surf.get_rect(center=(cx, rect.bottom - 16)))


